-- NFL Degenerates V2.13.2 (REVISED)\n-- Scheduler-only automatic score refresh.\n--\n-- BEFORE RUNNING:\n-- 1) V2.13.2 Revised must be deployed and manually verified.\n-- 2) AUTO_SYNC_TOKEN must already exist in Render.\n-- 3) Replace PASTE_THE_SAME_AUTO_SYNC_TOKEN_HERE with that exact token.\n\ncreate extension if not exists pg_cron;\ncreate extension if not exists pg_net with schema extensions;\n\ndo $$\ndeclare existing_job bigint;\nbegin\n  select jobid into existing_job\n  from cron.job\n  where jobname = 'nfl-degenerates-auto-score-refresh'\n  limit 1;\n  if existing_job is not null then\n    perform cron.unschedule(existing_job);\n  end if;\nend $$;\n\nselect vault.create_secret(\n  'https://nfl-degenerates-pool.onrender.com/api/system/score-refresh',\n  'nfl_degenerates_score_refresh_url'\n)\nwhere not exists (\n  select 1 from vault.decrypted_secrets\n  where name = 'nfl_degenerates_score_refresh_url'\n);\n\nselect vault.create_secret(\n  'PASTE_THE_SAME_AUTO_SYNC_TOKEN_HERE',\n  'nfl_degenerates_score_refresh_token'\n)\nwhere not exists (\n  select 1 from vault.decrypted_secrets\n  where name = 'nfl_degenerates_score_refresh_token'\n);\n\nselect cron.schedule(\n  'nfl-degenerates-auto-score-refresh',\n  '*/30 * * * *',\n  $cron$\n    select net.http_get(\n      url := (select decrypted_secret from vault.decrypted_secrets where name='nfl_degenerates_score_refresh_url' limit 1),\n      headers := jsonb_build_object(\n        'X-Auto-Sync-Token',\n        (select decrypted_secret from vault.decrypted_secrets where name='nfl_degenerates_score_refresh_token' limit 1)\n      ),\n      timeout_milliseconds := 120000\n    );\n  $cron$\n);\n\n-- Verify job:\n-- select jobid, jobname, schedule, active from cron.job\n-- where jobname='nfl-degenerates-auto-score-refresh';\n